<details class="comm-card"><summary>Automation plans, limits and template access</summary><?php if(empty($automation_admin['available'])): ?><div class="notice">Apply the Automation plans update on Central to configure workflow allowances and templates.</div><?php else: ?><p class="muted">Automation is a subscription, not a message-credit wallet. These limits count registered workflows, whether on or off. Archiving releases a slot. Plan and template changes are checked again before messages are sent.</p>
<div class="comm-grid"><?php foreach($automation_admin['plans'] as $plan):$open('automation_plan',array('plan_key'=>$plan['plan_key'])); ?><div class="comm-card"><label>Plan name<input name="name" value="<?= $h($plan['name']); ?>" maxlength="100" required></label><label>Workflow slots<input name="max_workflows" type="number" min="1" max="10000" value="<?= (int)$plan['max_workflows']; ?>" required></label><label>Monthly price (NGN)<input name="monthly" type="number" min="0" step="0.01" value="<?= $h($plan['monthly_kobo']/100); ?>" required></label><label>Annual price (NGN)<input name="annual" type="number" min="0" step="0.01" value="<?= $h($plan['annual_kobo']/100); ?>" required></label><label>Allowed templates</label><?php foreach($automation_admin['templates'] as $template): ?><label class="choice"><input type="checkbox" name="template_keys[]" value="<?= $h($template['template_key']); ?>" <?= in_array($template['template_key'],$plan['template_keys'],true)?'checked':''; ?>> <?= $h($template['name']); ?></label><?php endforeach; ?><label class="choice"><input type="checkbox" name="enabled" value="1" <?= $plan['enabled']?'checked':''; ?>> Plan available</label><button class="btn" style="margin-top:15px">Save plan</button></div><?= form_close();endforeach; ?></div>
<details><summary>Add another plan</summary><?php $open('automation_plan'); ?><div class="comm-split"><label>Plan key<input name="plan_key" pattern="[a-z][a-z0-9_]{1,39}" placeholder="plan_c" required></label><label>Plan name<input name="name" required></label><label>Workflow slots<input name="max_workflows" type="number" min="1" max="10000" required></label><label>Monthly (NGN)<input name="monthly" type="number" min="0" step="0.01" value="0" required></label><label>Annual (NGN)<input name="annual" type="number" min="0" step="0.01" value="0" required></label></div><?php foreach($automation_admin['templates'] as $template): ?><label class="choice"><input type="checkbox" name="template_keys[]" value="<?= $h($template['template_key']); ?>"> <?= $h($template['name']); ?></label><?php endforeach; ?><label class="choice"><input type="checkbox" name="enabled" value="1" checked> Available</label><button class="btn" style="margin:15px 0">Create plan</button><?= form_close(); ?></details>
<h2 style="margin-top:25px">Central automation templates</h2><?php foreach($automation_admin['templates'] as $template): ?><details class="comm-card"><summary><?= $h($template['name']); ?> · <?= $template['enabled']?'Enabled':'Disabled'; ?></summary><?php $open('automation_template',array('template_key'=>$template['template_key'])); ?><label>Name<input name="name" value="<?= $h($template['name']); ?>" required></label><label>Description<input name="description" value="<?= $h($template['description']); ?>" maxlength="500"></label><div class="comm-split"><label>Default audience<select name="segment_key"><?php foreach($segments as $key=>$definition): ?><option value="<?= $h($key); ?>" <?= $template['segment_key']===$key?'selected':''; ?>><?= $h($definition[0]); ?></option><?php endforeach; ?></select></label><label>Default interval (days)<input name="interval_days" type="number" min="1" max="365" value="<?= (int)$template['interval_days']; ?>" required></label></div><label>Subject<input name="subject" value="<?= $h($template['subject']); ?>" maxlength="255"></label><label>Message<textarea name="message" maxlength="20000" rows="4" required><?= $h($template['message']); ?></textarea></label><label class="choice"><input type="checkbox" name="enabled" value="1" <?= $template['enabled']?'checked':''; ?>> Template available</label><button class="btn" style="margin-top:15px">Save template</button><?= form_close(); ?></details><?php endforeach; ?>
<details class="comm-card"><summary>Add an automation template</summary><?php $open('automation_template'); ?><div class="comm-split"><label>Template key<input name="template_key" pattern="[a-z][a-z0-9_]{1,39}" required placeholder="lead_followup"></label><label>Name<input name="name" maxlength="100" required></label></div><label>Description<input name="description" maxlength="500"></label><div class="comm-split"><label>Default audience<select name="segment_key"><?php foreach($segments as $key=>$definition): ?><option value="<?= $h($key); ?>"><?= $h($definition[0]); ?></option><?php endforeach; ?></select></label><label>Default interval (days)<input name="interval_days" type="number" min="1" max="365" value="30" required></label></div><label>Subject<input name="subject" maxlength="255"></label><label>Message<textarea name="message" maxlength="20000" rows="4" required></textarea></label><label class="choice"><input name="enabled" type="checkbox" value="1" checked> Template available</label><button class="btn" style="margin-top:15px">Create template</button><?= form_close(); ?><p class="muted">After creating a template, choose which plans may use it above.</p></details>
<?php if(!empty($selected['communications']['automation']['available'])):$auto=$selected['communications']['automation']; ?><section class="comm-card"><h2>Selected account’s automation allowance</h2><p><?= $h($auto['plan']['name']??'No active plan'); ?> · <?= (int)$auto['used_workflows']; ?> / <?= (int)($auto['plan']['max_workflows']??0); ?> registered workflows</p><div class="comm-scroll"><table class="comm-table"><thead><tr><th>Workflow</th><th>Template</th><th>State</th></tr></thead><tbody><?php foreach($auto['registrations'] as $registration): ?><tr><td><?= $h($registration['name']); ?></td><td><?= $h($registration['template_key']); ?></td><td><?= $registration['enabled']?'On':'Off'; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<?php endif; ?></details>
